## solutions

#### depth first

```cpp
#include <unordered_map>
#include <vector>
#include <string>

bool hasPath(std::unordered_map<std::string, std::vector<std::string>> graph, std::string src, std::string dst) {
  if (src == dst) {
    return true;
  }

  for (std::string neighbor : graph[src]) {
    if (hasPath(graph, neighbor, dst) == true) {
      return true;
    }
  }

  return false;
}
```

- n = number of nodes
- e = number edges
- Time: O(e)
- Space: O(n)

#### breadth first

```cpp
#include <unordered_map>
#include <vector>
#include <string>
#include <queue>

bool hasPath(std::unordered_map<std::string, std::vector<std::string>> graph, std::string src, std::string dst) {
  std::queue<std::string> queue;
  queue.push(src);
  while (queue.size() > 0) {
    std::string current = queue.front();
    queue.pop();
    if (current == dst) {
      return true;
    }
    for (std::string neighbor : graph[current]) {
      queue.push(neighbor);
    }
  }
  return false;
}
```

- n = number of nodes
- e = number edges
- Time: O(e)
- Space: O(n)
